package pl.atrop.powerguard.bcknd.auth.domain; import java.util.Set; public record UserAccount(Long id,String username,String firstname,String lastname,String email,String phone,String passwordHash,UserRole role,boolean enabled,Set<Long> siteIds){public UserAccount{siteIds=siteIds==null?Set.of():Set.copyOf(siteIds);} public UserAccount withPasswordHash(String h){return new UserAccount(id,username,firstname,lastname,email,phone,h,role,enabled,siteIds);}}
